import torch


def run(x):
    return torch.special.log1p(x)


def _to_dtype(name):
    import torch
    return {
        "float16": torch.float16,
        "float32": torch.float32,
        "bfloat16": torch.bfloat16,
        "float64": torch.float64,
    }[name]


def gen_inputs(ctx, device):
    import torch
    shape = list(ctx["x__shape"])
    dtype = _to_dtype(ctx["x__dtype"])
    if dtype == torch.float64 and shape == [6]:
        # test_special_log1p_small_values
        x = torch.tensor(
            [1e-15, 1e-10, 1e-8, 1e-5, -1e-5, -1e-8],
            dtype=torch.float64,
            device=device,
        )
    elif shape == [4]:
        # test_special_log1p_negative (includes x <= -1 -> NaN)
        x = torch.tensor([-0.5, -0.99, -1.0, -2.0], dtype=dtype, device=device)
    elif shape == [3]:
        # test_special_log1p_nan_inf
        x = torch.tensor(
            [float("nan"), float("inf"), float("-inf")],
            dtype=dtype,
            device=device,
        )
    else:
        # test_special_log1p: torch.rand (uniform [0,1), domain-safe)
        x = torch.rand(shape, dtype=dtype, device=device)
    return {"x": x}


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch
    ref = ref_outputs[0].detach().to("cpu").to(torch.float64)
    sol = sol_outputs[0].detach().to("cpu").to(torch.float64)
    if ref.shape != sol.shape:
        return {"passed": False, "message": f"shape {sol.shape} vs {ref.shape}"}
    dt = ref_outputs[0].dtype
    if dt == torch.float16:
        rtol, atol = 1e-3, 1e-4
    elif dt == torch.bfloat16:
        rtol, atol = 1.6e-2, 1e-4
    elif dt == torch.float32:
        rtol, atol = 1.3e-6, 1e-4
    else:
        rtol, atol = 1e-7, 1e-4
    both_nan = torch.isnan(ref) & torch.isnan(sol)
    both_posinf = torch.isposinf(ref) & torch.isposinf(sol)
    both_neginf = torch.isneginf(ref) & torch.isneginf(sol)
    finite = torch.isfinite(ref) & torch.isfinite(sol)
    close = torch.zeros_like(ref, dtype=torch.bool)
    close[finite] = (ref[finite] - sol[finite]).abs() <= atol + rtol * ref[finite].abs()
    ok = (close | both_nan | both_posinf | both_neginf).all().item()
    return {"passed": bool(ok), "message": "", "metrics": {}}
